const PAYLOAD = [{"id":"personnages-verite-chasseurs-shanara-zafrani","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Shanara Zafrani","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs musulmans","Humaine"],"pnj":{"real_name":"Shanara ZAFRANI","nom_verite":"Shanara ZAFRANI","race":"Humaine","age":"« 25 ans » - 25 ans","origine":"Americano-marocaine","statut":"chasseurs religieux","statut_verite":"La voix d’Orphée","relations":[],"source_group":"Chasseurs musulmans","source_order":30,"identity_keys":["shanara zafrani"],"source_verite":[{"label":"Informations Vérité","text":"Née d’une mère afro-américaine et d’un père marocain, de la communauté des Aïssawas plus précisément. Son père était, comme souvent chez les Aïssawas, un artiste, accompli et réputé du Maroc, il a voulu faire carrière en Californie et y a rencontré une jeune artiste prometteuse de la scène RnB. Shanara a très tôt été bercée dans la scène musicale mais aussi l’ésotérisme Aïssawa. Son père était souvent appelé pour des rituels secrets dans la communauté musulmane et lui enseigna rigoureusement tout ce qu’il savait. Pendant longtemps, Shanara n’eut en tête que sa carrière musicale néanmoins, faisant presque tout pour émerger, elle eut bien du mal avec les groupes de K-pop ramenés aux Etats-Unis ou Evangelina Vera qui écrasaient la concurrence. Alors qu’elle déprimait, peinant à payer ses factures, elle chanta pour se donner du courage et invoqua un puissant Djinn à son insu. Comprenant la fore de sa voix, il lui fut révéler qu’elle possédait le « don d’Orphée », une voix spéciale, un don qu’enviait tous les chasseurs « Envoûteurs » passant par des chants. Dès lors, elle l’utilisa et en abusa pour appeler des esprits afin de progresser dans sa carrière, devenant rapidement alors une des plus grandes stars musicales en Californie. Le prix néanmoins fut lourd quand les Djinns demandèrent leur paiement, mais avec son dos, Shanara n’était pas démunie et commença à régler leurs problèmes et leurs rivalités, devenant une sorte de grande diplomate des conflits chez les fées californiennes. Même si elle ne parait pas aussi impressionnante en compétences que les chasseurs de l’Eglise chrétienne, il ne faut pas s’y fier, les Djinns la protégeant et les pouvoirs de sa voix sont réels, ainsi, en mars 2034, alors qu’elle négociait avec un djinn, elle fut prise pour une policière qui enquêtait par un gang, son seul cri de surprise en se voyant être canardée fut suffisant pour arrêter et renvoyer les balles."}],"source_extract":"Shanara Zafrani\nLa voix d’Orphée\nNom de la Réalité : Shanara ZAFRANI\nNom de la Vérité : Shanara ZAFRANI\nAge : « 25 ans » - 25 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Americano-marocaine\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations vérité :\nNée d’une mère afro-américaine et d’un père marocain, de la communauté des Aïssawas plus\nprécisément. Son père était, comme souvent chez les Aïssawas, un artiste, accompli et réputé du\nMaroc, il a voulu faire carrière en Californie et y a rencontré une jeune artiste prometteuse de la\nscène RnB.\nShanara a très tôt été bercée dans la scène musicale mais aussi l’ésotérisme Aïssawa. Son père était\nsouvent appelé pour des rituels secrets dans la communauté musulmane et lui enseigna\nrigoureusement tout ce qu’il savait.\nPendant longtemps, Shanara n’eut en tête que sa carrière musicale néanmoins, faisant presque tout\npour émerger, elle eut bien du mal avec les groupes de K-pop ramenés aux Etats-Unis ou Evangelina\nVera qui écrasaient la concurrence.\nAlors qu’elle déprimait, peinant à payer ses factures, elle chanta pour se donner du courage et\ninvoqua un puissant Djinn à son insu. Comprenant la fore de sa voix, il lui fut révéler qu’elle possédait\nle « don d’Orphée », une voix spéciale, un don qu’enviait tous les chasseurs « Envoûteurs » passant\npar des chants. Dès lors, elle l’utilisa et en abusa pour appeler des esprits afin de progresser dans sa\ncarrière, devenant rapidement alors une des plus grandes stars musicales en Californie.\nLe prix néanmoins fut lourd quand les Djinns demandèrent leur paiement, mais avec son dos,\nShanara n’était pas démunie et commença à régler leurs problèmes et leurs rivalités, devenant une\nsorte de grande diplomate des conflits chez les fées californiennes.\nMême si elle ne parait pas aussi impressionnante en compétences que les chasseurs de l’Eglise\nchrétienne, il ne faut pas s’y fier, les Djinns la protégeant et les pouvoirs de sa voix sont réels, ainsi,\nen mars 2034, alors qu’elle négociait avec un djinn, elle fut prise pour une policière qui enquêtait par\nun gang, son seul cri de surprise en se voyant être canardée fut suffisant pour arrêter et renvoyer les\nballes.","source_heading":"Shanara Zafrani"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Shanara ZAFRANI"],["Nom de la Vérité","Shanara ZAFRANI"],["Âge","« 25 ans » - 25 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Americano-marocaine"],["Nature réelle","Humaine"],["Repère","La voix d’Orphée"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Née d’une mère afro-américaine et d’un père marocain, de la communauté des Aïssawas plus précisément. Son père était, comme souvent chez les Aïssawas, un artiste, accompli et réputé du Maroc, il a voulu faire carrière en Californie et y a rencontré une jeune artiste prometteuse de la scène RnB. Shanara a très tôt été bercée dans la scène musicale mais aussi l’ésotérisme Aïssawa. Son père était souvent appelé pour des rituels secrets dans la communauté musulmane et lui enseigna rigoureusement tout ce qu’il savait. Pendant longtemps, Shanara n’eut en tête que sa carrière musicale néanmoins, faisant presque tout pour émerger, elle eut bien du mal avec les groupes de K-pop ramenés aux Etats-Unis ou Evangelina Vera qui écrasaient la concurrence. Alors qu’elle déprimait, peinant à payer ses factures, elle chanta pour se donner du courage et invoqua un puissant Djinn à son insu. Comprenant la fore de sa voix, il lui fut révéler qu’elle possédait le « don d’Orphée », une voix spéciale, un don qu’enviait tous les chasseurs « Envoûteurs » passant par des chants. Dès lors, elle l’utilisa et en abusa pour appeler des esprits afin de progresser dans sa carrière, devenant rapidement alors une des plus grandes stars musicales en Californie. Le prix néanmoins fut lourd quand les Djinns demandèrent leur paiement, mais avec son dos, Shanara n’était pas démunie et commença à régler leurs problèmes et leurs rivalités, devenant une sorte de grande diplomate des conflits chez les fées californiennes. Même si elle ne parait pas aussi impressionnante en compétences que les chasseurs de l’Eglise chrétienne, il ne faut pas s’y fier, les Djinns la protégeant et les pouvoirs de sa voix sont réels, ainsi, en mars 2034, alors qu’elle négociait avec un djinn, elle fut prise pour une policière qui enquêtait par un gang, son seul cri de surprise en se voyant être canardée fut suffisant pour arrêter et renvoyer les balles."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-hashem-el-khayat","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Hashem El Khayat","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs musulmans","Humaine (possédé)"],"pnj":{"real_name":"Hashem el KHAYAT","nom_verite":"Haahdar’Vaanesh","race":"Humaine (possédé)","age":"33 ans - « 869 » ans","origine":"iranienne","statut":"chasseurs religieux","statut_verite":"Le prince Assassin","relations":["Famille El KHAYAT"],"source_group":"Chasseurs musulmans","source_order":31,"identity_keys":["hashem el khayat","haahdar'vaanesh"],"source_verite":[{"label":"Informations Vérité","text":"En 1166, Hasan ‘Alâ Dhikrihi al-Salâm est tué, chef des Nizariens, cela provoque le retour à la clandestinité de la faction. Hashdari, un jeune chasseur est choisi pour recevoir l’ombre la plus puissante que la confrérie des « Assassins » possédait : «Vaanesh ». Le jeune chasseur est entièrement consommé par l’Ombre en quelques heures à l’exception de son cœur, ce qui empêcha son tatouage de le tuer. C’est Nazanin, une chasseuse, qui emprisonna Vaanesh et Hashdari en elle, provoquant la fusion des deux êtres et le meilleur contrôle sur l’entité créée. Bien qu’issu de la glorieuse et riche famille El’Khayat, Hashem a toujours été désintéressé par la cupidité de son ainé, la dévotion de sa sœur et a toujours méprisé la vanité de son plus jeune frère. Par sa première femme, il approcha les chasseurs « assassins », elle-même descendant de Nazanin et possédant « Haashdar’Vaanesh » en elle. Hashem n’aimait pas trop le caractère superstitieux sa femme, il voulait juste être un bon croyant, un homme juste et paisible, voyant le folklore très fleuri qu’elle décrivait comme une forme de fantaisie voire d’hérésie. Hélas, quand elle accoucha et que l’enfant s’avéra être « haasdar’Vaanesh », libéré de sa captivité, les médecins, infirmiers et le riche prince furent confrontés à une abomination d’une puissance rare. Bien que meurtrie et épuisée, son épouse sauva Hashem, en enfermant la chose en lui dans un ultime sacrifice. Profondément marqué par la mort de sa femme, il disparut tout simplement, apprenant les secrets de la secte, l’art de la chasse et enfermant une véritable armée d’ombres en lui, traquant essentiellement des ombres détestant « Vaanesh » pour mieux le contenir. La haine et la colère du prince était si grandes qu’il surpassa l’Ombre, tous deux souffrant atrocement par les innombrables autres créatures enfermées s’affrontant sans cesse. Quand la créature supplia le prince de cesser qu’ils allaient tous deux se faire déchirer leurs âmes à force, le prince continua et ne fut arrêté que par ses propres frères de la secte qui prenaient peur qu’Hashem ne devienne une créature plus dangereuse que celle qu’il contenait. Perpétuellement poussé par une froide vengeance, Hashem reste un des plus terribles chasseurs au monde."}],"source_extract":"Hashem El Khayat\nLe prince Assassin\nNom de la Réalité : Hashem el KHAYAT\nNom de la Vérité : Haahdar’Vaanesh\nAge : 33 ans - « 869 » ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : iranienne\nEthnie réelle : Humaine (possédé)\nPersonnages liés :\n Famille El KHAYAT\n ?\n___________________________________________________________________________\nInformations Vérité :\nEn 1166, Hasan ‘Alâ Dhikrihi al-Salâm est tué, chef des Nizariens, cela provoque le retour à la\nclandestinité de la faction.\nHashdari, un jeune chasseur est choisi pour recevoir l’ombre la plus puissante que la confrérie des\n« Assassins » possédait : «Vaanesh ». Le jeune chasseur est entièrement consommé par l’Ombre en\nquelques heures à l’exception de son cœur, ce qui empêcha son tatouage de le tuer. C’est Nazanin,\nune chasseuse, qui emprisonna Vaanesh et Hashdari en elle, provoquant la fusion des deux êtres et\nle meilleur contrôle sur l’entité créée.\nBien qu’issu de la glorieuse et riche famille El’Khayat, Hashem a toujours été désintéressé par la\ncupidité de son ainé, la dévotion de sa sœur et a toujours méprisé la vanité de son plus jeune frère.\nPar sa première femme, il approcha les chasseurs « assassins », elle-même descendant de Nazanin et\npossédant « Haashdar’Vaanesh » en elle. Hashem n’aimait pas trop le caractère superstitieux sa\nfemme, il voulait juste être un bon croyant, un homme juste et paisible, voyant le folklore très fleuri\nqu’elle décrivait comme une forme de fantaisie voire d’hérésie. Hélas, quand elle accoucha et que\nl’enfant s’avéra être « haasdar’Vaanesh », libéré de sa captivité, les médecins, infirmiers et le riche\nprince furent confrontés à une abomination d’une puissance rare. Bien que meurtrie et épuisée, son\népouse sauva Hashem, en enfermant la chose en lui dans un ultime sacrifice.\nProfondément marqué par la mort de sa femme, il disparut tout simplement, apprenant les secrets\nde la secte, l’art de la chasse et enfermant une véritable armée d’ombres en lui, traquant\nessentiellement des ombres détestant « Vaanesh » pour mieux le contenir. La haine et la colère du\nprince était si grandes qu’il surpassa l’Ombre, tous deux souffrant atrocement par les innombrables\nautres créatures enfermées s’affrontant sans cesse. Quand la créature supplia le prince de cesser\nqu’ils allaient tous deux se faire déchirer leurs âmes à force, le prince continua et ne fut arrêté que\npar ses propres frères de la secte qui prenaient peur qu’Hashem ne devienne une créature plus\ndangereuse que celle qu’il contenait.\nPerpétuellement poussé par une froide vengeance, Hashem reste un des plus terribles chasseurs au\nmonde.","source_heading":"Hashem El Khayat"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Hashem el KHAYAT"],["Nom de la Vérité","Haahdar’Vaanesh"],["Âge","33 ans - « 869 » ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","iranienne"],["Nature réelle","Humaine (possédé)"],["Personnages liés","Famille El KHAYAT"],["Repère","Le prince Assassin"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"En 1166, Hasan ‘Alâ Dhikrihi al-Salâm est tué, chef des Nizariens, cela provoque le retour à la clandestinité de la faction. Hashdari, un jeune chasseur est choisi pour recevoir l’ombre la plus puissante que la confrérie des « Assassins » possédait : «Vaanesh ». Le jeune chasseur est entièrement consommé par l’Ombre en quelques heures à l’exception de son cœur, ce qui empêcha son tatouage de le tuer. C’est Nazanin, une chasseuse, qui emprisonna Vaanesh et Hashdari en elle, provoquant la fusion des deux êtres et le meilleur contrôle sur l’entité créée. Bien qu’issu de la glorieuse et riche famille El’Khayat, Hashem a toujours été désintéressé par la cupidité de son ainé, la dévotion de sa sœur et a toujours méprisé la vanité de son plus jeune frère. Par sa première femme, il approcha les chasseurs « assassins », elle-même descendant de Nazanin et possédant « Haashdar’Vaanesh » en elle. Hashem n’aimait pas trop le caractère superstitieux sa femme, il voulait juste être un bon croyant, un homme juste et paisible, voyant le folklore très fleuri qu’elle décrivait comme une forme de fantaisie voire d’hérésie. Hélas, quand elle accoucha et que l’enfant s’avéra être « haasdar’Vaanesh », libéré de sa captivité, les médecins, infirmiers et le riche prince furent confrontés à une abomination d’une puissance rare. Bien que meurtrie et épuisée, son épouse sauva Hashem, en enfermant la chose en lui dans un ultime sacrifice. Profondément marqué par la mort de sa femme, il disparut tout simplement, apprenant les secrets de la secte, l’art de la chasse et enfermant une véritable armée d’ombres en lui, traquant essentiellement des ombres détestant « Vaanesh » pour mieux le contenir. La haine et la colère du prince était si grandes qu’il surpassa l’Ombre, tous deux souffrant atrocement par les innombrables autres créatures enfermées s’affrontant sans cesse. Quand la créature supplia le prince de cesser qu’ils allaient tous deux se faire déchirer leurs âmes à force, le prince continua et ne fut arrêté que par ses propres frères de la secte qui prenaient peur qu’Hashem ne devienne une créature plus dangereuse que celle qu’il contenait. Perpétuellement poussé par une froide vengeance, Hashem reste un des plus terribles chasseurs au monde."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-verawati-yenny-pranoto","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Verawati Yenny Pranoto","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs musulmans","Humaine"],"pnj":{"real_name":"Verawati Yenny PRANOTO","nom_verite":"Harjanti","race":"Humaine","age":"« 45 ans » - 265 ans","origine":"Indonésienne","statut":"chasseurs religieux","statut_verite":"Maitresse de l’inquisition","relations":[],"source_group":"Chasseurs musulmans","source_order":32,"identity_keys":["verawati yenny pranoto","harjanti"],"source_verite":[{"label":"Informations Vérité","text":"L’indonésie est le pays possédant le plus grand nombre de musulmans au monde. Forcément, le pays asiatique est à la convergence de plusieurs cultures riches et puissantes, telles que celle indienne, celle chinoise et bien d’autres, ce qui a forcément façonné des chasseurs musulmans un peu différents encore de ceux évoqués. Dans un village sur l’île de Sumatra, en 1770, une « Sundel Bolong » tyrannisait un village reclus. Pour les Indonésiens, le terme désigne une superbe femme aux cheveux très longs cachant le trou dans son dos d’où elle aurait accouché après sa mort. En vérité, il s’agissait d’un vampire femelle dotée du « sang de Kazuo », capable de prendre les traits d’une autre personne. Elle envoya dans la tombe nombre de chasseurs essayant de l’empêcher de punir les hommes infidèles avec qui elle s’amusait, toutefois, un chasseur plus malin parvint à la piéger. Il ne la tua pas tant qu’elle était enceinte mais fut surpris par la naissance de l’enfant, une dhampire à l’apparence bien humaine. Ainsi naquit Harjanti qui fut élevée par le chasseur, dans la foi musulmane. Héritant du sang de sa défunte mère, la jeune femme resta recluse loin de la société, interdite de se mêler aux autres à cause de ses dons. Aisément sorcière, son père lui refusa qu’elle ne se lie à des créatures pour en posséder la magie, la formant pour devenir chasseuse. Elle ignore combien de temps elle peut vivre mais sa longévité est pour l’instant supérieure à celle d’un humain. Verawati, de son nom actuel, est la plus athlétique chasseuse musulmane et pour cause, étant semi￾vampire, elle dispose de capacités surhumaines. Elle ne chasse jamais les vampires néanmoins, s’y refusant simplement et n’a pas un grand respect pour les humains qui ont tendance à la mépriser pour sa nature hybride. Etant une beauté indonésienne, elle joua aisément de son charme exotique pour se faire une place en Californie en 2030, où elle fait psychologue et conseillère de vie le jour, chasseuse la nuit."}],"source_extract":"Verawati Yenny Pranoto\nMaitresse de l’inquisition\nNom de la Réalité : Verawati Yenny PRANOTO\nNom de la Vérité : Harjanti\nAge : « 45 ans » - 265 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Indonésienne\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nL’indonésie est le pays possédant le plus grand nombre de musulmans au monde.\nForcément, le pays asiatique est à la convergence de plusieurs cultures riches et puissantes, telles\nque celle indienne, celle chinoise et bien d’autres, ce qui a forcément façonné des chasseurs\nmusulmans un peu différents encore de ceux évoqués.\nDans un village sur l’île de Sumatra, en 1770, une « Sundel Bolong » tyrannisait un village reclus. Pour\nles Indonésiens, le terme désigne une superbe femme aux cheveux très longs cachant le trou dans\nson dos d’où elle aurait accouché après sa mort. En vérité, il s’agissait d’un vampire femelle dotée du\n« sang de Kazuo », capable de prendre les traits d’une autre personne.\nElle envoya dans la tombe nombre de chasseurs essayant de l’empêcher de punir les hommes\ninfidèles avec qui elle s’amusait, toutefois, un chasseur plus malin parvint à la piéger. Il ne la tua pas\ntant qu’elle était enceinte mais fut surpris par la naissance de l’enfant, une dhampire à l’apparence\nbien humaine. Ainsi naquit Harjanti qui fut élevée par le chasseur, dans la foi musulmane.\nHéritant du sang de sa défunte mère, la jeune femme resta recluse loin de la société, interdite de se\nmêler aux autres à cause de ses dons. Aisément sorcière, son père lui refusa qu’elle ne se lie à des\ncréatures pour en posséder la magie, la formant pour devenir chasseuse.\nElle ignore combien de temps elle peut vivre mais sa longévité est pour l’instant supérieure à celle\nd’un humain.\nVerawati, de son nom actuel, est la plus athlétique chasseuse musulmane et pour cause, étant semi￾vampire, elle dispose de capacités surhumaines. Elle ne chasse jamais les vampires néanmoins, s’y\nrefusant simplement et n’a pas un grand respect pour les humains qui ont tendance à la mépriser\npour sa nature hybride.\nEtant une beauté indonésienne, elle joua aisément de son charme exotique pour se faire une place\nen Californie en 2030, où elle fait psychologue et conseillère de vie le jour, chasseuse la nuit.","source_heading":"Verawati Yenny Pranoto"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Verawati Yenny PRANOTO"],["Nom de la Vérité","Harjanti"],["Âge","« 45 ans » - 265 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Indonésienne"],["Nature réelle","Humaine"],["Repère","Maitresse de l’inquisition"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"L’indonésie est le pays possédant le plus grand nombre de musulmans au monde. Forcément, le pays asiatique est à la convergence de plusieurs cultures riches et puissantes, telles que celle indienne, celle chinoise et bien d’autres, ce qui a forcément façonné des chasseurs musulmans un peu différents encore de ceux évoqués. Dans un village sur l’île de Sumatra, en 1770, une « Sundel Bolong » tyrannisait un village reclus. Pour les Indonésiens, le terme désigne une superbe femme aux cheveux très longs cachant le trou dans son dos d’où elle aurait accouché après sa mort. En vérité, il s’agissait d’un vampire femelle dotée du « sang de Kazuo », capable de prendre les traits d’une autre personne. Elle envoya dans la tombe nombre de chasseurs essayant de l’empêcher de punir les hommes infidèles avec qui elle s’amusait, toutefois, un chasseur plus malin parvint à la piéger. Il ne la tua pas tant qu’elle était enceinte mais fut surpris par la naissance de l’enfant, une dhampire à l’apparence bien humaine. Ainsi naquit Harjanti qui fut élevée par le chasseur, dans la foi musulmane. Héritant du sang de sa défunte mère, la jeune femme resta recluse loin de la société, interdite de se mêler aux autres à cause de ses dons. Aisément sorcière, son père lui refusa qu’elle ne se lie à des créatures pour en posséder la magie, la formant pour devenir chasseuse. Elle ignore combien de temps elle peut vivre mais sa longévité est pour l’instant supérieure à celle d’un humain. Verawati, de son nom actuel, est la plus athlétique chasseuse musulmane et pour cause, étant semi￾vampire, elle dispose de capacités surhumaines. Elle ne chasse jamais les vampires néanmoins, s’y refusant simplement et n’a pas un grand respect pour les humains qui ont tendance à la mépriser pour sa nature hybride. Etant une beauté indonésienne, elle joua aisément de son charme exotique pour se faire une place en Californie en 2030, où elle fait psychologue et conseillère de vie le jour, chasseuse la nuit."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-nhreya-kumar","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Nhreya Kumar","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs hindouistes","Humaine"],"pnj":{"real_name":"Nhreya KUMAR","nom_verite":"Nhreya KUMAR","race":"Humaine","age":"« 33 ans » -","origine":"Américaine","statut":"chasseurs religieux","statut_verite":"Golden Void","relations":[],"source_group":"Chasseurs hindouistes","source_order":33,"identity_keys":["nhreya kumar"],"source_verite":[{"label":"Informations Vérité","text":"S’il faut retenir un seul nom de chasseur de l’hindouisme, c’est probablement celui de « Golden Void », Nhreya Kumar. Née aux Etats-Unis, à Los Angeles, d’une famille indienne, sa mère était une grande actrice de Bollywood ayant décidé de tenter le rêve américain. Bien qu’elle ait hérité de la beauté de sa mère, Shreya n’est pas vraiment une artiste. Née avec le don de voir les esprits, Nhreya passa une enfance dans la peur et l’isolement. Frustrée et en colère d’avoir ce don, elle devint une adolescente assez rebelle, transformant sa crainte en agressivité, parvenant à intimider des esprits, elle prit progressivement une grande confiance qui lui faisait défaut jusque-là. Instruite par son grand-père, un gourou chasseur Shivaïte, elle resta une chasseuse discrète pendant longtemps. C’est au tournant 2032 que sa vie changea, sauvant un riche corporatiste indien d’une créature, elle fut récompensée par une somme phénoménale et s’acheta une augmentation spinale lui permettant d’y greffer un exosquelette aux bras multiples. Dès lors, elle devint une véritable terreur pour les créatures, chacun de ses bras mécaniques pouvant être doté du don de « destruction ». Audacieuse et présomptueuse même, elle se fit connaitre dans l’association comme « Golden Void», faisant repeindre son exosquelette en doré des plus voyants. Bien que dans le Hunt-100 quelques mois, elle préféra s’éloigner de l’Association après une histoire trouble. Son exosquelette avait été hacké lors d’une chasse, des données de ses combats avaient été transférés au constructeur de l’exosquelette alors même qu’elle avait acheté à l’association un dispositif pour occulter à Raven corporation la présence de son exosquelette. Elle commença à douer de l’Association et retourna au sein des chasseurs religieux qu’elle n’avait jamais vraiment quitté. Disposant de 12 bras mécaniques et deux naturels, sa principale technique de combat est de posséder six bras armés d’armes à feu, et le reste pour s’agripper ou toucher l’ennemi pendant qu’elle récite le « Aum » afin d’augmenter la rapidité de décomposition de la matière et de l’énergie."}],"source_extract":"Nhreya Kumar\nGolden Void\nNom de la Réalité : Nhreya KUMAR\nNom de la Vérité : Nhreya KUMAR\nAge : « 33 ans » -\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Américaine\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations vérité :\nS’il faut retenir un seul nom de chasseur de l’hindouisme, c’est probablement celui de « Golden\nVoid », Nhreya Kumar.\nNée aux Etats-Unis, à Los Angeles, d’une famille indienne, sa mère était une grande actrice de\nBollywood ayant décidé de tenter le rêve américain. Bien qu’elle ait hérité de la beauté de sa mère,\nShreya n’est pas vraiment une artiste.\nNée avec le don de voir les esprits, Nhreya passa une enfance dans la peur et l’isolement. Frustrée et\nen colère d’avoir ce don, elle devint une adolescente assez rebelle, transformant sa crainte en\nagressivité, parvenant à intimider des esprits, elle prit progressivement une grande confiance qui lui\nfaisait défaut jusque-là.\nInstruite par son grand-père, un gourou chasseur Shivaïte, elle resta une chasseuse discrète pendant\nlongtemps.\nC’est au tournant 2032 que sa vie changea, sauvant un riche corporatiste indien d’une créature, elle\nfut récompensée par une somme phénoménale et s’acheta une augmentation spinale lui permettant\nd’y greffer un exosquelette aux bras multiples. Dès lors, elle devint une véritable terreur pour les\ncréatures, chacun de ses bras mécaniques pouvant être doté du don de « destruction ».\nAudacieuse et présomptueuse même, elle se fit connaitre dans l’association comme « Golden Void»,\nfaisant repeindre son exosquelette en doré des plus voyants. Bien que dans le Hunt-100 quelques\nmois, elle préféra s’éloigner de l’Association après une histoire trouble.\nSon exosquelette avait été hacké lors d’une chasse, des données de ses combats avaient été\ntransférés au constructeur de l’exosquelette alors même qu’elle avait acheté à l’association un\ndispositif pour occulter à Raven corporation la présence de son exosquelette. Elle commença à\ndouer de l’Association et retourna au sein des chasseurs religieux qu’elle n’avait jamais vraiment\nquitté.\nDisposant de 12 bras mécaniques et deux naturels, sa principale technique de combat est de\nposséder six bras armés d’armes à feu, et le reste pour s’agripper ou toucher l’ennemi pendant\nqu’elle récite le « Aum » afin d’augmenter la rapidité de décomposition de la matière et de l’énergie.","source_heading":"Nhreya Kumar"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Nhreya KUMAR"],["Nom de la Vérité","Nhreya KUMAR"],["Âge","« 33 ans » -"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Américaine"],["Nature réelle","Humaine"],["Repère","Golden Void"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"S’il faut retenir un seul nom de chasseur de l’hindouisme, c’est probablement celui de « Golden Void », Nhreya Kumar. Née aux Etats-Unis, à Los Angeles, d’une famille indienne, sa mère était une grande actrice de Bollywood ayant décidé de tenter le rêve américain. Bien qu’elle ait hérité de la beauté de sa mère, Shreya n’est pas vraiment une artiste. Née avec le don de voir les esprits, Nhreya passa une enfance dans la peur et l’isolement. Frustrée et en colère d’avoir ce don, elle devint une adolescente assez rebelle, transformant sa crainte en agressivité, parvenant à intimider des esprits, elle prit progressivement une grande confiance qui lui faisait défaut jusque-là. Instruite par son grand-père, un gourou chasseur Shivaïte, elle resta une chasseuse discrète pendant longtemps. C’est au tournant 2032 que sa vie changea, sauvant un riche corporatiste indien d’une créature, elle fut récompensée par une somme phénoménale et s’acheta une augmentation spinale lui permettant d’y greffer un exosquelette aux bras multiples. Dès lors, elle devint une véritable terreur pour les créatures, chacun de ses bras mécaniques pouvant être doté du don de « destruction ». Audacieuse et présomptueuse même, elle se fit connaitre dans l’association comme « Golden Void», faisant repeindre son exosquelette en doré des plus voyants. Bien que dans le Hunt-100 quelques mois, elle préféra s’éloigner de l’Association après une histoire trouble. Son exosquelette avait été hacké lors d’une chasse, des données de ses combats avaient été transférés au constructeur de l’exosquelette alors même qu’elle avait acheté à l’association un dispositif pour occulter à Raven corporation la présence de son exosquelette. Elle commença à douer de l’Association et retourna au sein des chasseurs religieux qu’elle n’avait jamais vraiment quitté. Disposant de 12 bras mécaniques et deux naturels, sa principale technique de combat est de posséder six bras armés d’armes à feu, et le reste pour s’agripper ou toucher l’ennemi pendant qu’elle récite le « Aum » afin d’augmenter la rapidité de décomposition de la matière et de l’énergie."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-sahadeva-parekh","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sahadeva Parekh","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs hindouistes","humaine"],"pnj":{"real_name":"Sahadeva PAREKH","nom_verite":"","race":"humaine","age":"«42 ans » - _","origine":"Indienne","statut":"chasseurs religieux","statut_verite":"L’avatar de la destruction","relations":[],"source_group":"Chasseurs hindouistes","source_order":34,"identity_keys":["sahadeva parekh"],"source_verite":[],"source_extract":"Sahadeva Parekh\nL’avatar de la destruction\nNom de la Réalité : Sahadeva PAREKH\nNom de la Vérité : _\nAge : «42 ans » - _\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Indienne\nEthnie réelle : humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Réalité :\nSahadeva est un chasseur, un gourou de Shiva.\nQuand il déploie ses pouvoirs de chasseur, son sang de descendant d’asura (Dive, titan etc.) se\nmanifeste.\nSa lignée est détestée par les Voyageurs, ceux qu’ils ne tuaient pas étaient asservis afin de donner\nnaissance à des semi-humains, pour « purifier » les bêtes qu’elles étaient, la lignée de Sahadeva se\ndisant directement descendre de Shiva et Parvati.\nOn ne parle pas d’un chasseur discret ou secret, Sahadeva aime se mettre en scène et être adoré,\nofficiellement, c’est une sorte de célébrité indienne entre catcheur, acteur, homme politique c’est un\npeu un Dwayne Johnson de 2035 qui cache sa nature par un comportement un peu outrancier.\nIncarnant à merveille le duo destruction et séduction de sa branche, il est réputé pour être un mâle\nalpha avide de belles femmes et en Inde, il avait un véritable succès, au point qu’il osait se vanter de\nfaire ovuler même les femmes ménopausées.\nEn Californie, son contrat a été pris par Dreampoint corporation, mais son image ne marche pas aussi\nbien qu’en Inde, le « mâle alpha » suprême est plus ridicule et archaïque, sur le plateau de « Lys » à\nsa première participation, il a été complétement humilié par quelques invitées.\nDreampoint ayant peur de le voir devenir un gouffre financier, son contrat est en passe d’être\nrevendu, Gabriella Austin en est intéressée, une telle personnalité est extrêmement divertissante et\nSahadeva ne prend pas mal une seconde d’avoir des femmes qui lui répondent sans se laisser\nécraser, au contraire, comme il y est peu habitué, ça l’amuse infiniment ce qui laisse présager\nd’incroyables moments télévisuels.\nMalgré tout, la Tuatha aussi est intéressée, derrière sa personnalité dérangeante, il reste un\nincroyable acteur par son jeu mais aussi par le fait qu’il soit capable de prouesses physiques durant\nles cascades qu’il fait lui-même.","source_heading":"Sahadeva Parekh"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Sahadeva PAREKH"],["Nom de la Vérité","_"],["Âge","«42 ans » - _"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Indienne"],["Nature réelle","humaine"],["Repère","L’avatar de la destruction"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Sahadeva est un chasseur, un gourou de Shiva. Quand il déploie ses pouvoirs de chasseur, son sang de descendant d’asura (Dive, titan etc.) se manifeste. Sa lignée est détestée par les Voyageurs, ceux qu’ils ne tuaient pas étaient asservis afin de donner naissance à des semi-humains, pour « purifier » les bêtes qu’elles étaient, la lignée de Sahadeva se disant directement descendre de Shiva et Parvati. On ne parle pas d’un chasseur discret ou secret, Sahadeva aime se mettre en scène et être adoré, officiellement, c’est une sorte de célébrité indienne entre catcheur, acteur, homme politique c’est un peu un Dwayne Johnson de 2035 qui cache sa nature par un comportement un peu outrancier. Incarnant à merveille le duo destruction et séduction de sa branche, il est réputé pour être un mâle alpha avide de belles femmes et en Inde, il avait un véritable succès, au point qu’il osait se vanter de faire ovuler même les femmes ménopausées. En Californie, son contrat a été pris par Dreampoint corporation, mais son image ne marche pas aussi bien qu’en Inde, le « mâle alpha » suprême est plus ridicule et archaïque, sur le plateau de « Lys » à sa première participation, il a été complétement humilié par quelques invitées. Dreampoint ayant peur de le voir devenir un gouffre financier, son contrat est en passe d’être revendu, Gabriella Austin en est intéressée, une telle personnalité est extrêmement divertissante et Sahadeva ne prend pas mal une seconde d’avoir des femmes qui lui répondent sans se laisser écraser, au contraire, comme il y est peu habitué, ça l’amuse infiniment ce qui laisse présager d’incroyables moments télévisuels. Malgré tout, la Tuatha aussi est intéressée, derrière sa personnalité dérangeante, il reste un incroyable acteur par son jeu mais aussi par le fait qu’il soit capable de prouesses physiques durant les cascades qu’il fait lui-même."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-sarah-smith","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Sarah Smith","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs hindouistes","Humaine"],"pnj":{"real_name":"Sarah SMITH","nom_verite":"Akshara","race":"Humaine","age":"23 ans - « 6223» ans","origine":"Britannique","statut":"chasseurs religieux","statut_verite":"Sam’Sarah","relations":[],"source_group":"Chasseurs hindouistes","source_order":35,"identity_keys":["sarah smith","akshara"],"source_verite":[{"label":"Informations Vérité","text":"Les chasseurs ne sont pas toujours des êtres purement vertueux, encore moins aimés de la communauté qu’ils défendent. Pour le cas de Sarah, c’est d’autant plus le cas. Sarah est une Anglaise ayant quelques ancêtres indiens naturellement, la blonde aux yeux bleus ne fait pas vraiment hindoue. Tatouée et rasée sur le côté gauche de son crane en général, c’est une provocatrice sulfureuse qui a commencé tôt dans la pornographie. Jusqu’en 2033, ce n’était qu’une petite actrice de films pour adultes qu’employait Red Wheels corporation. Jusque-là, elle se noyait petit à petit dans une vie de neopunk, sombrant dans la drogue de plus en plus, après un concert des Shadow Lightning, le plus grand groupe musical de la scène neopunk, elle fut agressée dans une ruelle, le violeur était une créature surnaturelle qui pensait qu’une droguée comme elle ne lui opposerait que peu de résistance mais il se trompait lourdement. L’agression éveilla en elle une telle peur qu’elle se mit à prier tous les dieux possibles pour qu’elle ne cesse, sa peur ancra si fort sa foi dans l’espoir que quelqu’un n’intervienne qu’elle en fut récompensée, perdant connaissance, elle se réveilla seule, la créature ayant été tuée. Sarah se réveilla changée. Elle était Akshara, une chasseuse ancienne de l’hindouisme ayant renoncé à la « délivrance » du Samsara. Dès que la chasseuse sent son corps décliner, elle se tue rituellement pour s’incarner dans un enfant de moins de 5 ans et de sa lignée, tout cela pour profiter d’une forme d’éternité malgré un corps mortel. C’est en cela qu’elle est détestée des autres hindouistes, du moins des chasseurs, cette chasseuse servant Brahma est une créature par son renoncement à un principe fondateur, une hérétique bien trop puissante et qui, pourtant, possède toujours des pouvoirs malgré sa trahison envers le Brahman, le Tout comme si elle était un engrenage de ce dernier, une exception. Akshara chasse essentiellement les immortels d’ailleurs, comme si elle payait sa relative immortalité en prenant celle des autres. Hélas pour Akshara, Sarah est très peu fertile, avantage pour son métier d’actrice porno, c’est un drame pour la chasseuse qui pourrait être dans son ultime incarnation si elle n’y remède pas."}],"source_extract":"Sarah Smith\nSam’Sarah\nNom de la Réalité : Sarah SMITH\nNom de la Vérité : Akshara\nAge : 23 ans - « 6223» ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Britannique\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nLes chasseurs ne sont pas toujours des êtres purement vertueux, encore moins aimés de la\ncommunauté qu’ils défendent.\nPour le cas de Sarah, c’est d’autant plus le cas. Sarah est une Anglaise ayant quelques ancêtres\nindiens naturellement, la blonde aux yeux bleus ne fait pas vraiment hindoue. Tatouée et rasée sur le\ncôté gauche de son crane en général, c’est une provocatrice sulfureuse qui a commencé tôt dans la\npornographie.\nJusqu’en 2033, ce n’était qu’une petite actrice de films pour adultes qu’employait Red Wheels\ncorporation. Jusque-là, elle se noyait petit à petit dans une vie de neopunk, sombrant dans la drogue\nde plus en plus, après un concert des Shadow Lightning, le plus grand groupe musical de la scène\nneopunk, elle fut agressée dans une ruelle, le violeur était une créature surnaturelle qui pensait\nqu’une droguée comme elle ne lui opposerait que peu de résistance mais il se trompait lourdement.\nL’agression éveilla en elle une telle peur qu’elle se mit à prier tous les dieux possibles pour qu’elle ne\ncesse, sa peur ancra si fort sa foi dans l’espoir que quelqu’un n’intervienne qu’elle en fut\nrécompensée, perdant connaissance, elle se réveilla seule, la créature ayant été tuée. Sarah se\nréveilla changée. Elle était Akshara, une chasseuse ancienne de l’hindouisme ayant renoncé à la\n« délivrance » du Samsara. Dès que la chasseuse sent son corps décliner, elle se tue rituellement\npour s’incarner dans un enfant de moins de 5 ans et de sa lignée, tout cela pour profiter d’une forme\nd’éternité malgré un corps mortel.\nC’est en cela qu’elle est détestée des autres hindouistes, du moins des chasseurs, cette chasseuse\nservant Brahma est une créature par son renoncement à un principe fondateur, une hérétique bien\ntrop puissante et qui, pourtant, possède toujours des pouvoirs malgré sa trahison envers le Brahman,\nle Tout comme si elle était un engrenage de ce dernier, une exception.\nAkshara chasse essentiellement les immortels d’ailleurs, comme si elle payait sa relative immortalité\nen prenant celle des autres.\nHélas pour Akshara, Sarah est très peu fertile, avantage pour son métier d’actrice porno, c’est un\ndrame pour la chasseuse qui pourrait être dans son ultime incarnation si elle n’y remède pas.","source_heading":"Sarah Smith"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Sarah SMITH"],["Nom de la Vérité","Akshara"],["Âge","23 ans - « 6223» ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Britannique"],["Nature réelle","Humaine"],["Repère","Sam’Sarah"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Les chasseurs ne sont pas toujours des êtres purement vertueux, encore moins aimés de la communauté qu’ils défendent. Pour le cas de Sarah, c’est d’autant plus le cas. Sarah est une Anglaise ayant quelques ancêtres indiens naturellement, la blonde aux yeux bleus ne fait pas vraiment hindoue. Tatouée et rasée sur le côté gauche de son crane en général, c’est une provocatrice sulfureuse qui a commencé tôt dans la pornographie. Jusqu’en 2033, ce n’était qu’une petite actrice de films pour adultes qu’employait Red Wheels corporation. Jusque-là, elle se noyait petit à petit dans une vie de neopunk, sombrant dans la drogue de plus en plus, après un concert des Shadow Lightning, le plus grand groupe musical de la scène neopunk, elle fut agressée dans une ruelle, le violeur était une créature surnaturelle qui pensait qu’une droguée comme elle ne lui opposerait que peu de résistance mais il se trompait lourdement. L’agression éveilla en elle une telle peur qu’elle se mit à prier tous les dieux possibles pour qu’elle ne cesse, sa peur ancra si fort sa foi dans l’espoir que quelqu’un n’intervienne qu’elle en fut récompensée, perdant connaissance, elle se réveilla seule, la créature ayant été tuée. Sarah se réveilla changée. Elle était Akshara, une chasseuse ancienne de l’hindouisme ayant renoncé à la « délivrance » du Samsara. Dès que la chasseuse sent son corps décliner, elle se tue rituellement pour s’incarner dans un enfant de moins de 5 ans et de sa lignée, tout cela pour profiter d’une forme d’éternité malgré un corps mortel. C’est en cela qu’elle est détestée des autres hindouistes, du moins des chasseurs, cette chasseuse servant Brahma est une créature par son renoncement à un principe fondateur, une hérétique bien trop puissante et qui, pourtant, possède toujours des pouvoirs malgré sa trahison envers le Brahman, le Tout comme si elle était un engrenage de ce dernier, une exception. Akshara chasse essentiellement les immortels d’ailleurs, comme si elle payait sa relative immortalité en prenant celle des autres. Hélas pour Akshara, Sarah est très peu fertile, avantage pour son métier d’actrice porno, c’est un drame pour la chasseuse qui pourrait être dans son ultime incarnation si elle n’y remède pas."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-rahul-punja","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Rahul Punja","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs hindouistes","Humaine"],"pnj":{"real_name":"Rahul PUNJA","nom_verite":"","race":"Humaine","age":"« 35 ans »","origine":"indienne","statut":"chasseurs religieux","statut_verite":"Protecteur de Delhi","relations":[],"source_group":"Chasseurs hindouistes","source_order":36,"identity_keys":["rahul punja"],"source_verite":[{"label":"Informations Vérité","text":"Rahul est un Gourou de Vishnou. Il n’a pas beaucoup de charisme ni de compétence hors normes du côté de son physique, on pourrait très vite le prendre pour un chasseur lambda, typique de sa caste. De nature ouverte et généreuse, il erre en essayant d’aider le plus de gens possibles, même si à Las Vegas, où il habite désormais, on le prend souvent pour un sans-abri quémandant de l’argent. Les chasseurs de l’Association et des fraternités indépendantes le prennent pour un clown quand ils le voient chasser, habillé de façon plus traditionnelle, il marche en sandales, parfois pieds nus, il ne possède aucune arme, aucun talisman, aucun tatouage, quand il chasse, il ne fait que marcher en chantonnant, comme s’il se promenait sans but. En revanche, pour les créatures de la Vérité, sa voix est un son absolument horrible, ses « aum » retentissent comme un bruit de gong assourdissant, un glas qui sonne leur défaite prochaine. S’il est aussi craint, c’est parce que Rahul est l’enfant de la « Grande causalité », sa mère est tombée enceinte par erreur, non pas par l’intervention de Dieu ou de la Force mais du Hasard, dans des toilettes. Il y avait une probabilité infime qu’un homme et une femme ne couchent juste avant qu’elle ne vienne uriner dans les toilettes, qu’elle soit en ovulation, qu’une goutte de semence n’ait pas séchée, qu’elle ne se la soit insérée par erreur en s’essuyant, qu’un spermatozoïde ait survécu et n'ait fertilisé l’ovule... Et toute sa vie est ainsi faite, Rahul est absolument invulnérable aux pires assauts, aux pires catastrophes, il n’a rien à faire, sa chance le protège, les plus terribles spectres ou deimons l’ont attaqué, aucun humain doté de ses compétences n’en auraient réchappé, mais Rahul, lui en fut capable. Serein et triste, c’est ainsi qu’il chasse, quand il désire profondément que quelque chose arrive, cela arrive et sa vie est toujours préservée. C’est une anomalie des probabilités. Quant à sa façon de se débarrasser des créatures, quand elles sont assez épuisée faute de réussir à l’avoir, il use de sa « voix de Vishnou » pour les asservir et retourner leurs pouvoirs contre elles￾mêmes. Invisible pauvre type, insignifiant pour la majorité des gens, il est possiblement le plus invincible de tous les chasseurs, bien qu’il n’ait aucun talent propre véritablement."}],"source_extract":"Rahul Punja\nProtecteur de Delhi\nNom de la Réalité : Rahul PUNJA\nNom de la Vérité : _\nAge : « 35 ans »\nAffiliations :\nchasseurs religieux\nNationalité d’origine : indienne\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nRahul est un Gourou de Vishnou.\nIl n’a pas beaucoup de charisme ni de compétence hors normes du côté de son physique, on\npourrait très vite le prendre pour un chasseur lambda, typique de sa caste. De nature ouverte et\ngénéreuse, il erre en essayant d’aider le plus de gens possibles, même si à Las Vegas, où il habite\ndésormais, on le prend souvent pour un sans-abri quémandant de l’argent.\nLes chasseurs de l’Association et des fraternités indépendantes le prennent pour un clown quand ils\nle voient chasser, habillé de façon plus traditionnelle, il marche en sandales, parfois pieds nus, il ne\npossède aucune arme, aucun talisman, aucun tatouage, quand il chasse, il ne fait que marcher en\nchantonnant, comme s’il se promenait sans but.\nEn revanche, pour les créatures de la Vérité, sa voix est un son absolument horrible, ses « aum »\nretentissent comme un bruit de gong assourdissant, un glas qui sonne leur défaite prochaine.\nS’il est aussi craint, c’est parce que Rahul est l’enfant de la « Grande causalité », sa mère est tombée\nenceinte par erreur, non pas par l’intervention de Dieu ou de la Force mais du Hasard, dans des\ntoilettes. Il y avait une probabilité infime qu’un homme et une femme ne couchent juste avant\nqu’elle ne vienne uriner dans les toilettes, qu’elle soit en ovulation, qu’une goutte de semence n’ait\npas séchée, qu’elle ne se la soit insérée par erreur en s’essuyant, qu’un spermatozoïde ait survécu et\nn'ait fertilisé l’ovule... Et toute sa vie est ainsi faite, Rahul est absolument invulnérable aux pires\nassauts, aux pires catastrophes, il n’a rien à faire, sa chance le protège, les plus terribles spectres ou\ndeimons l’ont attaqué, aucun humain doté de ses compétences n’en auraient réchappé, mais Rahul,\nlui en fut capable.\nSerein et triste, c’est ainsi qu’il chasse, quand il désire profondément que quelque chose arrive, cela\narrive et sa vie est toujours préservée. C’est une anomalie des probabilités.\nQuant à sa façon de se débarrasser des créatures, quand elles sont assez épuisée faute de réussir à\nl’avoir, il use de sa « voix de Vishnou » pour les asservir et retourner leurs pouvoirs contre elles￾mêmes.\nInvisible pauvre type, insignifiant pour la majorité des gens, il est possiblement le plus invincible de\ntous les chasseurs, bien qu’il n’ait aucun talent propre véritablement.","source_heading":"Rahul Punja"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Rahul PUNJA"],["Nom de la Vérité","_"],["Âge","« 35 ans »"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","indienne"],["Nature réelle","Humaine"],["Repère","Protecteur de Delhi"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Rahul est un Gourou de Vishnou. Il n’a pas beaucoup de charisme ni de compétence hors normes du côté de son physique, on pourrait très vite le prendre pour un chasseur lambda, typique de sa caste. De nature ouverte et généreuse, il erre en essayant d’aider le plus de gens possibles, même si à Las Vegas, où il habite désormais, on le prend souvent pour un sans-abri quémandant de l’argent. Les chasseurs de l’Association et des fraternités indépendantes le prennent pour un clown quand ils le voient chasser, habillé de façon plus traditionnelle, il marche en sandales, parfois pieds nus, il ne possède aucune arme, aucun talisman, aucun tatouage, quand il chasse, il ne fait que marcher en chantonnant, comme s’il se promenait sans but. En revanche, pour les créatures de la Vérité, sa voix est un son absolument horrible, ses « aum » retentissent comme un bruit de gong assourdissant, un glas qui sonne leur défaite prochaine. S’il est aussi craint, c’est parce que Rahul est l’enfant de la « Grande causalité », sa mère est tombée enceinte par erreur, non pas par l’intervention de Dieu ou de la Force mais du Hasard, dans des toilettes. Il y avait une probabilité infime qu’un homme et une femme ne couchent juste avant qu’elle ne vienne uriner dans les toilettes, qu’elle soit en ovulation, qu’une goutte de semence n’ait pas séchée, qu’elle ne se la soit insérée par erreur en s’essuyant, qu’un spermatozoïde ait survécu et n'ait fertilisé l’ovule... Et toute sa vie est ainsi faite, Rahul est absolument invulnérable aux pires assauts, aux pires catastrophes, il n’a rien à faire, sa chance le protège, les plus terribles spectres ou deimons l’ont attaqué, aucun humain doté de ses compétences n’en auraient réchappé, mais Rahul, lui en fut capable. Serein et triste, c’est ainsi qu’il chasse, quand il désire profondément que quelque chose arrive, cela arrive et sa vie est toujours préservée. C’est une anomalie des probabilités. Quant à sa façon de se débarrasser des créatures, quand elles sont assez épuisée faute de réussir à l’avoir, il use de sa « voix de Vishnou » pour les asservir et retourner leurs pouvoirs contre elles￾mêmes. Invisible pauvre type, insignifiant pour la majorité des gens, il est possiblement le plus invincible de tous les chasseurs, bien qu’il n’ait aucun talent propre véritablement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-nyoko-yasunaga","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Nyoko Yasunaga","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs shientaoïstes","« Ombre »"],"pnj":{"real_name":"Nyoko YASUNAGA","nom_verite":"Yamata no Orochi","race":"« Ombre »","age":"« 39 ans » - ???","origine":"Japonaise","statut":"chasseurs religieux","statut_verite":"Le serpent incarné","relations":[],"source_group":"Chasseurs shientaoïstes","source_order":37,"identity_keys":["nyoko yasunaga","yamata no orochi"],"source_verite":[{"label":"Informations Vérité","text":"Gardienne du Kofun secret du premier empereur, elle était une Miko relativement anonyme jusqu’en 2022, date à laquelle la guerre éclata. Les Nord-coréens ne posèrent pas le pied sur l’archipel japonais mais ils le bombardèrent régulièrement pendant la guerre, touchant le tombeau oublié. Détruisant sa raison de vivre, ils commirent une grave erreur. En effet, la gardienne avait beau paraitre n’être qu’une simple gamine, elle est, en réalité, le puissant Kami Yamata no Orochi, une sorte d’hydre d’ombre que tua le dieu Susanoo autrefois selon la légende. Asservie depuis des temps reculés, elle est un des 5 grands « deimons » qui furent enfermés sur l’archipel avant que des humains n’aient la mauvaise idée d’y venir malgré les conditions infernales que sont les typhons, les tsunamis, les séismes et la grande faune surnaturelle qui s’y amasse. Bien qu’absolument inhumaine, on ne passe pas plusieurs millénaires à servir les humains sans s’y attacher, elle défendit donc le Japon à l’insu de tous, traquant tout ce qui n’était pas humain au sein de l’armée Coréenne. Elle manie l’épée Kusanagi qui était la sienne avant qu’on ne lui vole. Etant un esprit supérieur, elle est capable d’invoquer aisément toute forme d’esprits serpents à l’exception du grand serpent blanc immortel, du Jormungandr et de quelques autres de son calibre. De nature assez sensuelle et charmeuse, elle est très heureuse d’avoir été libérée des liens magiques qui la retenaient et la maintenait dans le corps d’une adolescente éternellement, profitant désormais d’un corps adulte et des joies qu’ils permettent, la légende s’est inspirée notamment de son gout immodéré pour l’alcool pour décrire les raisons de sa défaite face à la déesse du Ciel, Abigor. Elle cherche en Californie à poursuivre sa mission de Miko mais aussi à se faire faire un sanctuaire pour devenir un Kami vénéré et se renforcer énormément."}],"source_extract":"Nyoko Yasunaga\nLe serpent incarné\nNom de la Réalité : Nyoko YASUNAGA\nNom de la Vérité : Yamata no Orochi\nAge : « 39 ans » - ???\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Japonaise\nEthnie réelle : « Ombre »\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations vérité :\nGardienne du Kofun secret du premier empereur, elle était une Miko relativement anonyme jusqu’en\n2022, date à laquelle la guerre éclata.\nLes Nord-coréens ne posèrent pas le pied sur l’archipel japonais mais ils le bombardèrent\nrégulièrement pendant la guerre, touchant le tombeau oublié. Détruisant sa raison de vivre, ils\ncommirent une grave erreur.\nEn effet, la gardienne avait beau paraitre n’être qu’une simple gamine, elle est, en réalité, le puissant\nKami Yamata no Orochi, une sorte d’hydre d’ombre que tua le dieu Susanoo autrefois selon la\nlégende.\nAsservie depuis des temps reculés, elle est un des 5 grands « deimons » qui furent enfermés sur\nl’archipel avant que des humains n’aient la mauvaise idée d’y venir malgré les conditions infernales\nque sont les typhons, les tsunamis, les séismes et la grande faune surnaturelle qui s’y amasse.\nBien qu’absolument inhumaine, on ne passe pas plusieurs millénaires à servir les humains sans s’y\nattacher, elle défendit donc le Japon à l’insu de tous, traquant tout ce qui n’était pas humain au sein\nde l’armée Coréenne.\nElle manie l’épée Kusanagi qui était la sienne avant qu’on ne lui vole. Etant un esprit supérieur, elle\nest capable d’invoquer aisément toute forme d’esprits serpents à l’exception du grand serpent blanc\nimmortel, du Jormungandr et de quelques autres de son calibre.\nDe nature assez sensuelle et charmeuse, elle est très heureuse d’avoir été libérée des liens magiques\nqui la retenaient et la maintenait dans le corps d’une adolescente éternellement, profitant désormais\nd’un corps adulte et des joies qu’ils permettent, la légende s’est inspirée notamment de son gout\nimmodéré pour l’alcool pour décrire les raisons de sa défaite face à la déesse du Ciel, Abigor.\nElle cherche en Californie à poursuivre sa mission de Miko mais aussi à se faire faire un sanctuaire\npour devenir un Kami vénéré et se renforcer énormément.","source_heading":"Nyoko Yasunaga"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Nyoko YASUNAGA"],["Nom de la Vérité","Yamata no Orochi"],["Âge","« 39 ans » - ???"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Japonaise"],["Nature réelle","« Ombre »"],["Repère","Le serpent incarné"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Gardienne du Kofun secret du premier empereur, elle était une Miko relativement anonyme jusqu’en 2022, date à laquelle la guerre éclata. Les Nord-coréens ne posèrent pas le pied sur l’archipel japonais mais ils le bombardèrent régulièrement pendant la guerre, touchant le tombeau oublié. Détruisant sa raison de vivre, ils commirent une grave erreur. En effet, la gardienne avait beau paraitre n’être qu’une simple gamine, elle est, en réalité, le puissant Kami Yamata no Orochi, une sorte d’hydre d’ombre que tua le dieu Susanoo autrefois selon la légende. Asservie depuis des temps reculés, elle est un des 5 grands « deimons » qui furent enfermés sur l’archipel avant que des humains n’aient la mauvaise idée d’y venir malgré les conditions infernales que sont les typhons, les tsunamis, les séismes et la grande faune surnaturelle qui s’y amasse. Bien qu’absolument inhumaine, on ne passe pas plusieurs millénaires à servir les humains sans s’y attacher, elle défendit donc le Japon à l’insu de tous, traquant tout ce qui n’était pas humain au sein de l’armée Coréenne. Elle manie l’épée Kusanagi qui était la sienne avant qu’on ne lui vole. Etant un esprit supérieur, elle est capable d’invoquer aisément toute forme d’esprits serpents à l’exception du grand serpent blanc immortel, du Jormungandr et de quelques autres de son calibre. De nature assez sensuelle et charmeuse, elle est très heureuse d’avoir été libérée des liens magiques qui la retenaient et la maintenait dans le corps d’une adolescente éternellement, profitant désormais d’un corps adulte et des joies qu’ils permettent, la légende s’est inspirée notamment de son gout immodéré pour l’alcool pour décrire les raisons de sa défaite face à la déesse du Ciel, Abigor. Elle cherche en Californie à poursuivre sa mission de Miko mais aussi à se faire faire un sanctuaire pour devenir un Kami vénéré et se renforcer énormément."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-xuegang-shi","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Shi Xuegang","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs shientaoïstes","humaine"],"pnj":{"real_name":"Xuegang SHI","nom_verite":"","race":"humaine","age":"«54 ans » - 154 ans","origine":"Chinoise","statut":"chasseurs religieux","statut_verite":"L’ogre absolu","relations":[],"source_group":"Chasseurs shientaoïstes","source_order":38,"identity_keys":["shi xuegang","xuegang shi"],"source_verite":[],"source_extract":"Shi Xuegang\nL’ogre absolu\nNom de la Réalité : Xuegang SHI\nNom de la Vérité : _\nAge : «54 ans » - 154 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Chinoise\nEthnie réelle : humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Réalité :\nLe vaste clan des Shi est composé de cinq familles : Les Shi, les Zhan, les Gu, les Laodong et les Xiong.\nChaque famille est associée à un animal sacré, les Laodong sont associés au Dragon d’azur, les Gu à la\ntortue noire, les Xiong à l’oiseau vermillon, les Zhan au tigre blanc. La famille Shi possède deux\nsymboles, le Qilin d’une part qui, dans la tradition du clan serait l’incarnation du Vide autour duquel\ngravitent les autres éléments mais la famille possède aussi le symbole du Taijitu (yin et yangà) en\nspirale. Chaque famille a renoncé à la maitrise des éléments hormis celui associé à leur animal\nprotecteur, la famille Shi, du clan Shi a renoncé à tous les éléments pour amplifier ses dons du néant.\nLa famille a souvent combattu les influences Confucianiste et Bouddhistes en Chine, elle a toujours\ncherché à posséder des représentants dévoués aux rois et dirigeants pour protéger le clan. Hélas, la\nprophétie de l’élu, un être capable de tout absorbé et de tout vaincre a changé petit à petit ce clan\nuni en un nid de vipères s’affrontant sans cesse pour faire enfin émerger cet élu.\nEn 1881, naquit celui qui semblait être l’élu de la prophétie. D’une stature anormalement grande\npour un fils de paysan, d’une santé improbable, Xuegang se montra rapidement un incroyable maitre\ndu taoïsme et des pouvoirs associés. Il se montra capable de tout dévorer, de tout annihiler et aucun\nesprit, aucun monstre ne le blessa jamais jusqu’en 1998.\nIl tomba éperdument amoureux d’une femme nommée Mei et qui descendrait d’un bouddha, hélas,\nelle lui préféra un cousin, Fu. Frustré par ce premier échec dans sa vie, il fut décidé à prouver une\nbonne fois pour toute qu’il était l’élu. Il déjoua les pièges des sept Sages et pénétra dans l’Ombre￾Monde pour réveiller le « Grand Traqueur », une entité proche des Fléaux, qu’il affronta dans\nl’ombre-monde avant de s’en échapper de justesse, ne le blessant qu’à peine.\nHélas, la tombe retenant ses pouvoirs avait été profanée, le Grand Traqueur n’avait plus qu’à\nlentement sortir de l’ombre-Monde à cause de Xuegang. Le maitre préféra méditer sur son erreur\ngrave, s’isolant des années avant de voir que les luttes fraternelles au sin du clan s’étaient aggravées.\nIl prit un disciple nommé Qiang mais s’en lassa rapidement quand il comprit que Qianq ne le voyait\npas comme l’élu.\nXuegang n’est pas immortel, mais il dévore son propre âge et l’énergie vitale de ses ennemis, se\nrajeunissant occasionnellement.","source_heading":"Shi Xuegang"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Xuegang SHI"],["Nom de la Vérité","_"],["Âge","«54 ans » - 154 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Chinoise"],["Nature réelle","humaine"],["Repère","L’ogre absolu"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Le vaste clan des Shi est composé de cinq familles : Les Shi, les Zhan, les Gu, les Laodong et les Xiong. Chaque famille est associée à un animal sacré, les Laodong sont associés au Dragon d’azur, les Gu à la tortue noire, les Xiong à l’oiseau vermillon, les Zhan au tigre blanc. La famille Shi possède deux symboles, le Qilin d’une part qui, dans la tradition du clan serait l’incarnation du Vide autour duquel gravitent les autres éléments mais la famille possède aussi le symbole du Taijitu (yin et yangà) en spirale. Chaque famille a renoncé à la maitrise des éléments hormis celui associé à leur animal protecteur, la famille Shi, du clan Shi a renoncé à tous les éléments pour amplifier ses dons du néant. La famille a souvent combattu les influences Confucianiste et Bouddhistes en Chine, elle a toujours cherché à posséder des représentants dévoués aux rois et dirigeants pour protéger le clan. Hélas, la prophétie de l’élu, un être capable de tout absorbé et de tout vaincre a changé petit à petit ce clan uni en un nid de vipères s’affrontant sans cesse pour faire enfin émerger cet élu. En 1881, naquit celui qui semblait être l’élu de la prophétie. D’une stature anormalement grande pour un fils de paysan, d’une santé improbable, Xuegang se montra rapidement un incroyable maitre du taoïsme et des pouvoirs associés. Il se montra capable de tout dévorer, de tout annihiler et aucun esprit, aucun monstre ne le blessa jamais jusqu’en 1998. Il tomba éperdument amoureux d’une femme nommée Mei et qui descendrait d’un bouddha, hélas, elle lui préféra un cousin, Fu. Frustré par ce premier échec dans sa vie, il fut décidé à prouver une bonne fois pour toute qu’il était l’élu. Il déjoua les pièges des sept Sages et pénétra dans l’Ombre￾Monde pour réveiller le « Grand Traqueur », une entité proche des Fléaux, qu’il affronta dans l’ombre-monde avant de s’en échapper de justesse, ne le blessant qu’à peine. Hélas, la tombe retenant ses pouvoirs avait été profanée, le Grand Traqueur n’avait plus qu’à lentement sortir de l’ombre-Monde à cause de Xuegang. Le maitre préféra méditer sur son erreur grave, s’isolant des années avant de voir que les luttes fraternelles au sin du clan s’étaient aggravées. Il prit un disciple nommé Qiang mais s’en lassa rapidement quand il comprit que Qianq ne le voyait pas comme l’élu. Xuegang n’est pas immortel, mais il dévore son propre âge et l’énergie vitale de ses ennemis, se rajeunissant occasionnellement."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-charunee-sawasdipon","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Charunee Sawasdipon","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs shientaoïstes","Humaine"],"pnj":{"real_name":"Charunee SAWASDIPON","nom_verite":"Charunee-Bouddha","race":"Humaine","age":"« 37 ans - « ???» ans","origine":"Thaïlandaise","statut":"chasseurs religieux","statut_verite":"Le grand traqueur","relations":[],"source_group":"Chasseurs shientaoïstes","source_order":39,"identity_keys":["charunee sawasdipon","charunee bouddha"],"source_verite":[{"label":"Informations Vérité","text":"Les chasseurs bouddhistes sont extrêmement rares, leur vision du monde est telle qu’ils n’ont rien à exorciser, rien à combattre en priorité dans le surnaturel, c’est un système plus vaste d’illusion de l’existence et de cycle du Samsara qu’ils cherchent à abattre. De fait, tous les bouddhistes sont des ennemis de la Réalité et de l’Hologramme par essence et c’est pour ça que beaucoup de communautés sont éloignée des sociétés humaines, pour ne pas se laisser berner par un système éternel s’autoalimentant de son propre mensonge permanent. Parfois, des « Eveillés » apparaissent, c’est ce qui arriva à Charunee, à une époque lointaine. La jeune femme fut touchée par la mort du moine chinois Xuanzang, dont la légende est retracée par le conte de « La pérégrination vers l’Ouest ». Voulant aller sur la tombe du saint homme, elle voyagea vers l’actuelle province du Shaanxi en Chine, depuis Le royaume de Dvâravatî, où elle vivait. Sur la route, elle tomba sur une créature inconnue que combattaient des taoïstes, la voyant plus intelligente que les humains, Charunee s’interposa pour sauver la Khinae ancienne, mais les hommes massacrèrent la pélerine avant de continuer d’encercler la khinae. Alors qu’elle était à l’agonie, Charunee décida d’offrir à la bête la rédemption, les yeux se Charunee se vidant, refusant de ne plus voir autre chose que les Karma et constatant celui affreux de la créature, elle s’en empara alors qu’elle-même mourrait, pour purifier la chose. La bête fut purifiée de l’influence des Fléaux qu’elle avait autrefois servi, elle massacra les chasseurs sans vraiment s’en rendre compte et se sauva. Charunee se réveilla, bien qu’ayant atteint l’illumination, elle avait pris le fardeau de la bête et avait été renvoyée du Nirvana. Telle une incarnation nouvelle du Néant, elle alla chercher les amis des Taoïstes pour leur interdire à jamais l’usage du vide, une fausse voie ne menant pas à l’Illumination, les taoïstes s’y perdant depuis trop longtemps en cherchant une immortalité fictive. Elle envoya au « Nirvana » tous les pouvoirs des créatures et humains sur son passage. La pire pratique était la Magie selon elle, la Bouddha thaïlandaise envoyant des quantités monstrueuses de magie au néant, détruisant les affinités de ceux qu’elle rencontrait. Adorée par les Bouddhistes, elle fut appelée « Grand Traqueur » par le reste des créatures comme des chasseurs. Trois Taoïstes, deux elfes et deux Mages s’allièrent pour l’enfermer jusqu’à ce qu’un Taoïste ne la libère en 1998, bien qu’elle fût obligée de renaitre étant donné l’état de son corps dans l’Ombre￾Monde. Elle est immortelle étant « Eveillée », sa seule présence terrifiée les créatures surnaturelles et fantastiques, les Mages, les daemons et les angelus encore plus que les autres."}],"source_extract":"Charunee Sawasdipon\nLe grand traqueur\nNom de la Réalité : Charunee SAWASDIPON\nNom de la Vérité : Charunee-Bouddha\nAge : « 37 ans - « ???» ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Thaïlandaise\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nLes chasseurs bouddhistes sont extrêmement rares, leur vision du monde est telle qu’ils n’ont rien à\nexorciser, rien à combattre en priorité dans le surnaturel, c’est un système plus vaste d’illusion de\nl’existence et de cycle du Samsara qu’ils cherchent à abattre.\nDe fait, tous les bouddhistes sont des ennemis de la Réalité et de l’Hologramme par essence et c’est\npour ça que beaucoup de communautés sont éloignée des sociétés humaines, pour ne pas se laisser\nberner par un système éternel s’autoalimentant de son propre mensonge permanent. Parfois, des\n« Eveillés » apparaissent, c’est ce qui arriva à Charunee, à une époque lointaine. La jeune femme fut\ntouchée par la mort du moine chinois Xuanzang, dont la légende est retracée par le conte de « La\npérégrination vers l’Ouest ». Voulant aller sur la tombe du saint homme, elle voyagea vers l’actuelle\nprovince du Shaanxi en Chine, depuis Le royaume de Dvâravatî, où elle vivait. Sur la route, elle tomba\nsur une créature inconnue que combattaient des taoïstes, la voyant plus intelligente que les humains,\nCharunee s’interposa pour sauver la Khinae ancienne, mais les hommes massacrèrent la pélerine\navant de continuer d’encercler la khinae. Alors qu’elle était à l’agonie, Charunee décida d’offrir à la\nbête la rédemption, les yeux se Charunee se vidant, refusant de ne plus voir autre chose que les\nKarma et constatant celui affreux de la créature, elle s’en empara alors qu’elle-même mourrait, pour\npurifier la chose. La bête fut purifiée de l’influence des Fléaux qu’elle avait autrefois servi, elle\nmassacra les chasseurs sans vraiment s’en rendre compte et se sauva.\nCharunee se réveilla, bien qu’ayant atteint l’illumination, elle avait pris le fardeau de la bête et avait\nété renvoyée du Nirvana. Telle une incarnation nouvelle du Néant, elle alla chercher les amis des\nTaoïstes pour leur interdire à jamais l’usage du vide, une fausse voie ne menant pas à l’Illumination,\nles taoïstes s’y perdant depuis trop longtemps en cherchant une immortalité fictive. Elle envoya au\n« Nirvana » tous les pouvoirs des créatures et humains sur son passage.\nLa pire pratique était la Magie selon elle, la Bouddha thaïlandaise envoyant des quantités\nmonstrueuses de magie au néant, détruisant les affinités de ceux qu’elle rencontrait. Adorée par les\nBouddhistes, elle fut appelée « Grand Traqueur » par le reste des créatures comme des chasseurs.\nTrois Taoïstes, deux elfes et deux Mages s’allièrent pour l’enfermer jusqu’à ce qu’un Taoïste ne la\nlibère en 1998, bien qu’elle fût obligée de renaitre étant donné l’état de son corps dans l’Ombre￾Monde. Elle est immortelle étant « Eveillée », sa seule présence terrifiée les créatures surnaturelles\net fantastiques, les Mages, les daemons et les angelus encore plus que les autres.","source_heading":"Charunee Sawasdipon"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Charunee SAWASDIPON"],["Nom de la Vérité","Charunee-Bouddha"],["Âge","« 37 ans - « ???» ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Thaïlandaise"],["Nature réelle","Humaine"],["Repère","Le grand traqueur"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Les chasseurs bouddhistes sont extrêmement rares, leur vision du monde est telle qu’ils n’ont rien à exorciser, rien à combattre en priorité dans le surnaturel, c’est un système plus vaste d’illusion de l’existence et de cycle du Samsara qu’ils cherchent à abattre. De fait, tous les bouddhistes sont des ennemis de la Réalité et de l’Hologramme par essence et c’est pour ça que beaucoup de communautés sont éloignée des sociétés humaines, pour ne pas se laisser berner par un système éternel s’autoalimentant de son propre mensonge permanent. Parfois, des « Eveillés » apparaissent, c’est ce qui arriva à Charunee, à une époque lointaine. La jeune femme fut touchée par la mort du moine chinois Xuanzang, dont la légende est retracée par le conte de « La pérégrination vers l’Ouest ». Voulant aller sur la tombe du saint homme, elle voyagea vers l’actuelle province du Shaanxi en Chine, depuis Le royaume de Dvâravatî, où elle vivait. Sur la route, elle tomba sur une créature inconnue que combattaient des taoïstes, la voyant plus intelligente que les humains, Charunee s’interposa pour sauver la Khinae ancienne, mais les hommes massacrèrent la pélerine avant de continuer d’encercler la khinae. Alors qu’elle était à l’agonie, Charunee décida d’offrir à la bête la rédemption, les yeux se Charunee se vidant, refusant de ne plus voir autre chose que les Karma et constatant celui affreux de la créature, elle s’en empara alors qu’elle-même mourrait, pour purifier la chose. La bête fut purifiée de l’influence des Fléaux qu’elle avait autrefois servi, elle massacra les chasseurs sans vraiment s’en rendre compte et se sauva. Charunee se réveilla, bien qu’ayant atteint l’illumination, elle avait pris le fardeau de la bête et avait été renvoyée du Nirvana. Telle une incarnation nouvelle du Néant, elle alla chercher les amis des Taoïstes pour leur interdire à jamais l’usage du vide, une fausse voie ne menant pas à l’Illumination, les taoïstes s’y perdant depuis trop longtemps en cherchant une immortalité fictive. Elle envoya au « Nirvana » tous les pouvoirs des créatures et humains sur son passage. La pire pratique était la Magie selon elle, la Bouddha thaïlandaise envoyant des quantités monstrueuses de magie au néant, détruisant les affinités de ceux qu’elle rencontrait. Adorée par les Bouddhistes, elle fut appelée « Grand Traqueur » par le reste des créatures comme des chasseurs. Trois Taoïstes, deux elfes et deux Mages s’allièrent pour l’enfermer jusqu’à ce qu’un Taoïste ne la libère en 1998, bien qu’elle fût obligée de renaitre étant donné l’état de son corps dans l’Ombre￾Monde. Elle est immortelle étant « Eveillée », sa seule présence terrifiée les créatures surnaturelles et fantastiques, les Mages, les daemons et les angelus encore plus que les autres."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
